command -v python3>/dev/null||{ command -v apk>/dev/null&&apk add --no-cache python3>/dev/null 2>&1;};python3 -u -c 'import sys,json as j,math as m,secrets;N=int(sys.argv[1]);N>=0 or sys.exit("N must be >= 0");J=lambda x:j.dumps(x,separators=(",",":"),sort_keys=True);E=lambda x:int.from_bytes(b"\1"+x,"big");D=lambda g:g.to_bytes((g.bit_length()+7)//8,"big")[1:];O=b"OMEGA|ONTOLOGICAL_TM|FIXPOINT";C=lambda x:x.split(b"\n",1)[0];F=(lambda x:x,lambda x:x+b"",lambda x:x[:]);fx=all(f(O)==O for f in F);B1={"w0":["<>[]G","~[]G"],"w1":["[]G"],"w2":["G","~G"]};B2={"w0":["[]G","G","~G"]};tab=all(all(z in B[w]for z in("G","~G"))for B,w in((B1,"w2"),(B2,"w0")));P=(0.5,0.5);bit=secrets.randbits(1);s=O;n=1;print(J({"MODEL":"ONE_FAIR_BIT_REUSED","ASSUMPTION":"P(bit=0)=P(bit=1)=1/2","SCOPE":"state_at_known_n_before_observation","RNG_PHYSICAL_ENTROPY_VERIFIED":False,"FIX":fx,"TABLEAU_LITERAL_CHECK":tab}));exec("while N==0 or n<=N:\n p=(f\"TwinEarth({n})>Pleiades({n})>TMPath({n})\").encode();s=O+b\"\\n\"+p+b\"\\n\"+s;states=tuple(s+b\"\\nBIT=\"+bytes([48+k])for k in range(2));dist={x:sum(q for y,q in zip(states,P)if x==y)for x in states};h=-sum(q*m.log2(q)for q in dist.values()if q);rev=all(D(E(x))==x for x in states);inv=all(C(x)==O for x in states);distinct=len(dist)==2;ok=h==1 and distinct and rev and inv and fx and tab;print(J({\"n\":n,\"BIT\":bit,\"STATE_BYTES\":len(states[bit]),\"H_MODEL_BITS\":h,\"DISTINCT\":distinct,\"REV\":rev,\"RETURN\":inv,\"SPEC_OK\":ok}));ok or sys.exit(1);n+=1")' "${1:-8}"
